// Returns the indices of the top-2 values among (i, j, k),
// ordered so that valores[first] >= valores[second].
fn torneo(valores: &Vec<i32>, i: usize, j: usize, k: usize) -> (usize, usize) {
    // Helper: given two indices, return them ordered by descending value.
    // If values tie, keep the given order (any tie-breaking is acceptable).
    fn order2(valores: &Vec<i32>, a: usize, b: usize) -> (usize, usize) {
        if valores[a] >= valores[b] { (a, b) } else { (b, a) }
    }

    // First, pick the best of (i, j)
    let (best_ij, other_ij) = order2(valores, i, j);

    // Compare the winner with k to find the overall maximum
    if valores[best_ij] >= valores[k] {
        // best_ij is the maximum; second best is max(other_ij, k)
        let (second, _) = order2(valores, other_ij, k);
        (best_ij, second)
    } else {
        // k is the maximum; second best is best_ij
        (k, best_ij)
    }
}